onClick:
{{
  q_hr_get_employee_by_id.run()
    .then(() => {
      resetWidget("inpEditFullName");
      resetWidget("inpEditEmail");
      resetWidget("selEditRole");
      resetWidget("inpEditDepartment");
      resetWidget("inpEditDesignation");
      resetWidget("selEditReportingManager");
      resetWidget("dpEditJoiningDate");

      showAlert(
        "Employee details have been reset successfully.",
        "success"
      );
    })
    .catch(error => {
      showAlert(
        error.message || "Unable to reset employee details.",
        "error"
      );
    })
}}
